# Let me find all connected components of 3s and see the structure
from collections import deque

def find_connected_components(grid, val):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == val and (r, c) not in visited:
                comp = []
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    comp.append((cr, cc))
                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == val and (nr, nc) not in visited:
                            queue.append((nr, nc))
                components.append(comp)
    return components

# Find connected components of 3s
threes = find_connected_components(grid, 3)
print(f"Found {len(threes)} connected components of 3s:")
for i, comp in enumerate(threes):
    print(f"\nComponent {i} with {len(comp)} cells:")
    for r, c in sorted(comp):
        print(f"  ({r}, {c})")

